/**
 * 宿主归一化：
 * - 原始酒馆预设中的空槽位依赖酒馆运行时注入，项目已经由自己的世界书/玩家档案管线提供，不能继续作为空条目展示。
 * - assistant 条目是酒馆的示例/预填充协议；项目统一以 system 提示提交，避免部分 API 拒绝尾部 assistant 消息而直接中止请求。
 */
export const DRC_V12_PROMPTS: PresetPromptEntry[] = DRC_V12_SOURCE_PROMPTS
  .filter(entry => entry.content.trim().length > 0)
  .map(entry => {
    const normalized = entry.role === 'assistant' ? { ...entry, role: 'system' as const } : entry;
    return DRC_LEGACY_PERSPECTIVE_IDS.has(normalized.identifier) || DRC_DISABLED_DRAFT_IDS.has(normalized.identifier)
      ? { ...normalized, enabled: false }
      : normalized;
  });

